def scan_token_burn_from_logs():
    """Scans local engine traces to calculate average tokens per run."""
    candidate_logs = [
        "artifacts/logs/engine_trace.jsonl",
        "artifacts/logs/llm_audit_enhanced.jsonl",
        "artifacts/logs/llm_audit.jsonl"
    ]
    prompt_tokens = []
    completion_tokens = []
    
    for log_path in candidate_logs:
        if os.path.exists(log_path):
            try:
                with open(log_path, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            data = json.loads(line)
                            p = data.get("prompt_tokens") or data.get("prompt_eval_count") or 0
                            c = data.get("output_tokens") or data.get("eval_count") or 0
                            if p > 0:
                                prompt_tokens.append(p)
                            if c > 0:
                                completion_tokens.append(c)
                        except json.JSONDecodeError:
                            continue
            except Exception:
                pass
            if prompt_tokens:
                break
                
    if prompt_tokens:
        avg_in = int(sum(prompt_tokens) / len(prompt_tokens))
        avg_out = int(sum(completion_tokens) / len(completion_tokens)) if completion_tokens else 35000
        print(f"[INFO] Detected token burn from logs: ~{avg_in:,} Prompt Tokens, ~{avg_out:,} Output Tokens")
        return avg_in, avg_out
    else:
        print("[INFO] No log files found in artifacts/logs/; using standard baseline token volume.")
        return 150000, 45000

def calculate_costs(args):
    # Effective USD to INR conversion rate with GST and Forex markup
    # Effective Rate = Base Rate * (1 + GST / 100) * (1 + Forex / 100)
    effective_inr_rate = args.usd_inr * (1 + args.gst_pct / 100.0) * (1 + args.forex_pct / 100.0)
    
    creation_in = args.creation_in
    creation_out = args.creation_out
    triage_in = args.triage_in
    triage_out = args.triage_out
    browser_cost = args.browser_cost
    small_runs = 500
    ent_runs = args.enterprise_runs
    
    usd_rows = []
    inr_rows = []
    
    for m in PRICING_CATALOG:
        in_p = m["input_per_1m"]
        out_p = m["output_per_1m"]
        
        # Test creation stage cost
        creation_cost = (creation_in / 1_000_000.0 * in_p) + (creation_out / 1_000_000.0 * out_p)
        # Post-run triage stage cost (10 failures)
        triage_cost = (triage_in / 1_000_000.0 * in_p) + (triage_out / 1_000_000.0 * out_p)
        
        # Playwright browser cost applies to all cloud options or standard execution
        runner_cost = browser_cost
        
        # Total cost per single run
        total_run_usd = creation_cost + triage_cost + runner_cost
        monthly_small_usd = total_run_usd * small_runs
        monthly_ent_usd = total_run_usd * ent_runs
        annual_ent_usd = monthly_ent_usd * 12.0
        
        usd_rows.append({
            "provider": m["provider"],
            "in_p": f"${in_p:.2f}",
            "out_p": f"${out_p:.2f}",
            "creation": f"${creation_cost:.2f}",
            "triage": f"${triage_cost:.2f}",
            "browser": f"${runner_cost:.3f}",
            "total_run": f"${total_run_usd:.3f}",
            "monthly_small": f"${monthly_small_usd:,.2f}",
            "monthly_ent": f"${monthly_ent_usd:,.2f}",
            "annual_ent": f"${annual_ent_usd:,.2f}",
            "_annual_val": annual_ent_usd,
            "_run_val": total_run_usd
        })
        
        # INR computations
        in_p_inr = in_p * effective_inr_rate
        out_p_inr = out_p * effective_inr_rate
        creation_inr = creation_cost * effective_inr_rate
        triage_inr = triage_cost * effective_inr_rate
        browser_inr = runner_cost * effective_inr_rate
        total_run_inr = total_run_usd * effective_inr_rate
        monthly_small_inr = monthly_small_usd * effective_inr_rate
        monthly_ent_inr = monthly_ent_usd * effective_inr_rate
        annual_ent_inr = annual_ent_usd * effective_inr_rate
        
        inr_rows.append({
            "provider": m["provider"],
            "in_p": f"Rs.{in_p_inr:.2f}",
            "out_p": f"Rs.{out_p_inr:.2f}",
            "creation": f"Rs.{creation_inr:.2f}",
            "triage": f"Rs.{triage_inr:.2f}",
            "browser": f"Rs.{browser_inr:.2f}",
            "total_run": f"Rs.{total_run_inr:.2f}",
            "monthly_small": f"Rs.{monthly_small_inr:,.2f}",
            "monthly_ent": f"Rs.{monthly_ent_inr:,.2f}",
            "annual_ent": f"Rs.{annual_ent_inr:,.2f}",
            "_annual_val": annual_ent_inr,
            "_run_val": total_run_inr
        })
        
    return usd_rows, inr_rows, effective_inr_rate

def build_usd_table(usd_rows):
    header = "| Model / Provider | Input Price / 1M | Output Price / 1M | Test Creation Cost | Post-Run Triage Cost (10 Failures) | Playwright Cloud Runner | Total Cost per Full Lifecycle Run | Monthly Bill: Small Team (500 Runs) | Monthly Bill: Enterprise CI/CD (1,500 Runs) | Annual Cloud Bill (1,500 Runs / mo) |\n"
    divider = "| :--- | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: |\n"
    lines = [header, divider]
    for r in usd_rows:
        lines.append(f"| {r['provider']} | {r['in_p']} | {r['out_p']} | {r['creation']} | {r['triage']} | {r['browser']} | {r['total_run']} | {r['monthly_small']} | {r['monthly_ent']} | {r['annual_ent']} |\n")
    return "".join(lines).strip()

def build_inr_table(inr_rows):
    header = "| Model / Provider | Input Price / 1M (Rs.) | Output Price / 1M (Rs.) | Test Creation (Rs.) | Post-Run Triage (10 Failures) (Rs.) | Playwright Cloud (Rs.) | Total Cost per Single Run (Rs.) | Monthly Bill: Small Team (500 Runs) | Monthly Bill: Enterprise CI/CD (1,500 Runs) | Annual Cloud Bill (1,500 Runs / mo) |\n"
    divider = "| :--- | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: | :---: |\n"
    lines = [header, divider]
    for r in inr_rows:
        lines.append(f"| {r['provider']} | {r['in_p']} | {r['out_p']} | {r['creation']} | {r['triage']} | {r['browser']} | {r['total_run']} | {r['monthly_small']} | {r['monthly_ent']} | {r['annual_ent']} |\n")
    return "".join(lines).strip()

def build_roi_summary(usd_rows, inr_rows, laptop_cost_inr):
    claude_inr = inr_rows[0]
    sovereign_inr = inr_rows[6]
    
    annual_claude = claude_inr["_annual_val"]
    annual_sovereign = sovereign_inr["_annual_val"]
    annual_savings = annual_claude - annual_sovereign
    
    annual_claude_lakh = annual_claude / 100000.0
    annual_savings_lakh = annual_savings / 100000.0
    
    power_kwh_cost_annual = 1650.0  # standard commercial peak tariff estimate
    net_laptop_cost = laptop_cost_inr + power_kwh_cost_annual
    
    daily_claude_bill = (annual_claude / 12.0) / 22.0  # 22 business days/month
    daily_sovereign_bill = (annual_sovereign / 12.0) / 22.0
    daily_net_saving = max(1.0, daily_claude_bill - daily_sovereign_bill)
    
    break_even_days = round(net_laptop_cost / daily_net_saving, 1)
    
    summary = f"""> [!TIP]
> **Enterprise Financial Payback & ROI (Indian Market Reality)**:
> * **Annual Cloud Bleed**: An Indian tech team or IT services enterprise executing 1500 automated regression runs/month on Claude 3.5 Sonnet spends **Rs.{annual_claude:,.2f} ({annual_claude_lakh:.2f} L) annually** in cloud API invoices.
> * **One-Time Laptop CapEx in India**: An off-the-shelf developer laptop (Lenovo LOQ / Acer Nitro / ASUS TUF with NVIDIA RTX 3050 4GB VRAM) costs **Rs.{laptop_cost_inr:,.2f}**.
> * **Power Consumption**: Drawing ~80W TDP during CUDA inference at commercial peak tariff (Rs.8.50/kWh) costs **~Rs.{power_kwh_cost_annual:,.0f} per year**.
> * **Break-Even Velocity**: The entire laptop pays for itself in just **{break_even_days} business days** compared to Claude 3.5 Sonnet!
> * **Annual Net Capital Retained**: Saves over **Rs.{annual_savings:,.2f} ({annual_savings_lakh:.2f} L) every single year per QA squad** while maintaining 100% data sovereignty."""
    return summary

def update_readme_file(readme_path, usd_table, inr_table, roi_summary):
    if not os.path.exists(readme_path):
        print(f"[ERROR] README file not found at: {readme_path}")
        return False
        
    with open(readme_path, "r", encoding="utf-8") as f:
        content = f.read()
        
    # Replace USD table
    usd_pattern = r"(<!-- BEGIN_COST_MATRIX_USD\n).*?(\nEND_COST_MATRIX_USD -->)"
    usd_replacement = r"\g<1>" + usd_table + r"\g<2>"
    if re.search(usd_pattern, content, flags=re.DOTALL):
        content = re.sub(usd_pattern, usd_replacement, content, flags=re.DOTALL)
    else:
        print("[WARN] Marker <!-- BEGIN_COST_MATRIX_USD --> not found in README.")

    # Replace INR table
    inr_pattern = r"(<!-- BEGIN_COST_MATRIX_INR\n).*?(\nEND_COST_MATRIX_INR -->)"
    inr_replacement = r"\g<1>" + inr_table + r"\g<2>"
    if re.search(inr_pattern, content, flags=re.DOTALL):
        content = re.sub(inr_pattern, inr_replacement, content, flags=re.DOTALL)
    else:
        print("[WARN] Marker <!-- BEGIN_COST_MATRIX_INR --> not found in README.")

    # Replace ROI summary
    roi_pattern = r"(<!-- BEGIN_ROI_SUMMARY\n).*?(\nEND_ROI_SUMMARY -->)"
    roi_replacement = r"\g<1>" + roi_summary + r"\g<2>"
    if re.search(roi_pattern, content, flags=re.DOTALL):
        content = re.sub(roi_pattern, roi_replacement, content, flags=re.DOTALL)
    else:
        print("[WARN] Marker <!-- BEGIN_ROI_SUMMARY --> not found in README.")

    with open(readme_path, "w", encoding="utf-8") as f:
        f.write(content)
        
    print(f"[SUCCESS] Updated cost matrices and ROI summary in {readme_path} in-place.")
    return True

def main():
    parser = argparse.ArgumentParser(description="Enterprise ATP Inference Cost & ROI Calculator")
    parser.add_argument("--update-readme", action="store_true", help="Overwrites the cost tables and ROI in README.md in-place")
    parser.add_argument("--readme-path", default="README.md", help="Path to README.md (default: README.md)")
    parser.add_argument("--from-logs", action="store_true", help="Scans local logs to extract average prompt/output tokens")
    parser.add_argument("--usd-inr", type=float, default=87.00, help="Base USD to INR exchange rate (default: 87.00)")
    parser.add_argument("--gst-pct", type=float, default=18.0, help="Indian statutory GST percentage on cloud SaaS (default: 18.0)")
    parser.add_argument("--forex-pct", type=float, default=3.5, help="Bank forex and card conversion markup percentage (default: 3.5)")
    parser.add_argument("--creation-in", type=int, default=150000, help="Input tokens for Test Creation stage (default: 150000)")
    parser.add_argument("--creation-out", type=int, default=45000, help="Output tokens for Test Creation stage (default: 45000)")
    parser.add_argument("--triage-in", type=int, default=125000, help="Input tokens for Triage stage per 10 failures (default: 125000)")
    parser.add_argument("--triage-out", type=int, default=25000, help="Output tokens for Triage stage per 10 failures (default: 25000)")
    parser.add_argument("--browser-cost", type=float, default=0.20, help="Cloud browser runner execution fee per 50-test run in USD (default: $0.20)")
    parser.add_argument("--runs-per-month", type=int, default=1500, dest="enterprise_runs", help="Enterprise monthly test runs (default: 1500)")
    parser.add_argument("--enterprise-runs", type=int, default=1500, help="Enterprise monthly test runs (default: 1500)")
    parser.add_argument("--laptop-cost-inr", type=float, default=65000.0, help="Local developer laptop cost in INR (default: Rs.65,000)")

    args = parser.parse_args()
    
    if args.from_logs:
        in_tok, out_tok = scan_token_burn_from_logs()
        args.creation_in = in_tok
        args.creation_out = out_tok

    usd_rows, inr_rows, effective_rate = calculate_costs(args)
    usd_table = build_usd_table(usd_rows)
    inr_table = build_inr_table(inr_rows)
    roi_summary = build_roi_summary(usd_rows, inr_rows, args.laptop_cost_inr)

    print("\n" + "=" * 100)
    print(f"ENTERPRISE ATP FULL-LIFECYCLE COST MATRIX (USD)")
    print(f"Token Profile: Creation={args.creation_in:,} In / {args.creation_out:,} Out | Triage={args.triage_in:,} In / {args.triage_out:,} Out")
    print("=" * 100)
    print(usd_table)
    
    print("\n" + "=" * 100)
    print(f"ENTERPRISE ATP FULL-LIFECYCLE COST MATRIX (INR / Rs.)")
    print(f"Exchange Rate: 1 USD = Rs.{args.usd_inr:.2f} + {args.gst_pct}% GST + {args.forex_pct}% Forex = Effective Rs.{effective_rate:.2f}/USD")
    print("=" * 100)
    print(inr_table)
    print("\n" + roi_summary + "\n")

    if args.update_readme:
        update_readme_file(args.readme_path, usd_table, inr_table, roi_summary)

if __name__ == "__main__":
    main()
''')
    create_file("scripts/calculate_and_update_readme_costs.py", r'''#!/usr/bin/env python3
