    create_file('config/__init__.py', '"""Configuration package initialization."""\nfrom .settings import settings\n\n__all__ = ["settings"]\n')
    create_file('config/settings.py', '"""\nconfig/settings.py\nEnterprise Configuration Engine utilizing Pydantic Settings with graceful fallback.\nSafely extracts OS environment variables with deterministic fallbacks for local and CI runners.\n"""\n\nimport os\nfrom typing import Dict\n\ntry:\n    from pydantic_settings import BaseSettings, SettingsConfigDict\n    from pydantic import Field, HttpUrl\n\n    class AutomationSettings(BaseSettings):\n        model_config = SettingsConfigDict(\n            env_file=".env",\n            env_file_encoding="utf-8",\n            case_sensitive=False,\n            extra="ignore"\n        )\n\n        # Base Application Routing\n        base_url: str = Field(\n            default="https://staging.example.internal",\n            description="Base URL for target application under test"\n        )\n\n        # CI/CD Execution Toggles\n        headless: bool = Field(\n            default=True,\n            description="Execute browser engines in headless mode for CI/CD runners"\n        )\n        browser_timeout_ms: int = Field(\n            default=30000,\n            description="Explicit timeout threshold in milliseconds"\n        )\n\n        # WAF & Security Allowlist Contracts\n        waf_bypass_header_name: str = Field(\n            default="X-Automation-Bypass-Token",\n            description="WAF rule matching header name"\n        )\n        waf_bypass_token: str = Field(\n            default="ci-secret-token-allowlist-stage-2026",\n            description="Shared secret injected into browser network requests"\n        )\n\n        # Official Cloudflare Turnstile Testing Keys\n        # Source: https://developers.cloudflare.com/turnstile/troubleshooting/testing/\n        turnstile_always_passes_sitekey: str = Field(\n            default="1x00000000000000000000AA",\n            description="Cloudflare official test sitekey that always yields a successful challenge token"\n        )\n        turnstile_always_fails_sitekey: str = Field(\n            default="2x00000000000000000000AB",\n            description="Cloudflare official test sitekey that forces a failure response"\n        )\n\n        @property\n        def waf_headers_dict(self) -> Dict[str, str]:\n            """Returns header dictionary formatted for HTTP context injection."""\n            return {self.waf_bypass_header_name: self.waf_bypass_token}\n\n    settings = AutomationSettings()\n\nexcept ImportError:\n    # Standard library fallback if pydantic-settings is not installed in local environment\n    class AutomationSettings:\n        def __init__(self) -> None:\n            self.base_url: str = os.getenv("BASE_URL", "https://staging.example.internal")\n            self.headless: bool = os.getenv("HEADLESS", "true").lower() in ("true", "1", "yes")\n            self.browser_timeout_ms: int = int(os.getenv("BROWSER_TIMEOUT_MS", "30000"))\n            self.waf_bypass_header_name: str = os.getenv("WAF_BYPASS_HEADER_NAME", "X-Automation-Bypass-Token")\n            self.waf_bypass_token: str = os.getenv("WAF_BYPASS_TOKEN", "ci-secret-token-allowlist-stage-2026")\n            self.turnstile_always_passes_sitekey: str = os.getenv(\n                "TURNSTILE_ALWAYS_PASSES_SITEKEY", "1x00000000000000000000AA"\n            )\n            self.turnstile_always_fails_sitekey: str = os.getenv(\n                "TURNSTILE_ALWAYS_FAILS_SITEKEY", "2x00000000000000000000AB"\n            )\n\n        @property\n        def waf_headers_dict(self) -> Dict[str, str]:\n            """Returns header dictionary formatted for HTTP context injection."""\n            return {self.waf_bypass_header_name: self.waf_bypass_token}\n\n    settings = AutomationSettings()\n')
