    create_file('libraries/PyppeteerKeywords.py', '"""\nlibraries/PyppeteerKeywords.py\nCustom Robot Framework keyword library wrapping pyppeteer.\nImplements non-blocking async execution inside Robot\'s synchronous test runner.\n"""\n\nimport asyncio\nfrom typing import Optional, Dict, Any\n\ntry:\n    from pyppeteer import launch\n    from pyppeteer.browser import Browser\n    from pyppeteer.page import Page\nexcept ImportError:\n    launch = None\n    Browser = Any  # type: ignore\n    Page = Any     # type: ignore\n\nfrom config.settings import settings\n\n\nclass PyppeteerKeywords:\n    """Robot Framework keyword bridge for custom Pyppeteer automation flows."""\n    ROBOT_LIBRARY_SCOPE = \'SUITE\'\n    ROBOT_LIBRARY_VERSION = \'1.0.0\'\n\n    def __init__(self) -> None:\n        self.loop: asyncio.AbstractEventLoop = asyncio.new_event_loop()\n        asyncio.set_event_loop(self.loop)\n        self.browser: Optional[Browser] = None\n        self.page: Optional[Page] = None\n\n    def _run_async(self, coroutine):\n        """Executes coroutine in the dedicated event loop."""\n        return self.loop.run_until_complete(coroutine)\n\n    def launch_headless_pyppeteer_with_headers(self) -> None:\n        """\n        Initializes a headless Chromium process with WAF headers and CI arguments.\n        Robot Keyword: Launch Headless Pyppeteer With Headers\n        """\n        if launch is None:\n            raise ImportError("pyppeteer is not installed. Run \'poetry install\' or \'pip install pyppeteer\'.")\n\n        async def _launch():\n            launch_args = [\n                \'--no-sandbox\',\n                \'--disable-setuid-sandbox\',\n                \'--disable-dev-shm-usage\',\n                \'--disable-gpu\',\n                \'--window-size=1920,1080\',\n            ]\n            self.browser = await launch(\n                headless=settings.headless,\n                args=launch_args,\n                defaultViewport={\'width\': 1920, \'height\': 1080},\n                autoClose=False\n            )\n            self.page = await self.browser.newPage()\n            # Inject WAF bypass headers across all network requests\n            await self.page.setExtraHTTPHeaders(settings.waf_headers_dict)\n\n        self._run_async(_launch())\n\n    def open_url_and_sync(self, url: str) -> None:\n        """\n        Navigates to URL and waits for network idle state.\n        Robot Keyword: Open URL And Sync\n        """\n        async def _navigate():\n            if not self.page:\n                raise RuntimeError("Pyppeteer page has not been initialized. Call \'Launch Headless Pyppeteer With Headers\' first.")\n            await self.page.goto(url, {\'waitUntil\': \'networkidle2\', \'timeout\': settings.browser_timeout_ms})\n\n        self._run_async(_navigate())\n\n    def wait_for_loader_to_hide(self, selector: str = "#app-loader", timeout_ms: Optional[int] = None) -> None:\n        """\n        Waits for a dynamic spinner or loader container to transition to hidden.\n        Robot Keyword: Wait For Loader To Hide\n        """\n        timeout = timeout_ms if timeout_ms is not None else settings.browser_timeout_ms\n\n        async def _wait_loader():\n            if not self.page:\n                raise RuntimeError("Pyppeteer page is unavailable.")\n            # {\'hidden\': True} waits until the element is either detached from DOM or has display:none/visibility:hidden\n            await self.page.waitForSelector(selector, {\'hidden\': True, \'timeout\': timeout})\n\n        self._run_async(_wait_loader())\n\n    def teardown_pyppeteer(self) -> None:\n        """\n        Gracefully terminates browser process to prevent orphaned processes.\n        Robot Keyword: Teardown Pyppeteer\n        """\n        async def _teardown():\n            if self.page:\n                await self.page.close()\n                self.page = None\n            if self.browser:\n                await self.browser.close()\n                self.browser = None\n\n        if self.browser:\n            self._run_async(_teardown())\n')
    create_file('tests/suite_playwright.robot', '*** Settings ***\nDocumentation       Enterprise CI/CD Suite for Playwright-backed Browser Library.\n...                 Demonstrates WAF Header Injection, Spinner Detachment, and\n...                 Cloudflare Turnstile testing sitekey interaction.\nLibrary             Browser\nVariables           ../config/settings.py\nSuite Setup         Initialize Enterprise Browser Context\nSuite Teardown      Close Browser    ALL\n\n*** Variables ***\n${SPINNER_LOCATOR}          css=#app-loader\n${REGISTRATION_FORM}        css=#registration-form\n${EMAIL_INPUT}              css=input[type="email"]\n${SUBMIT_BUTTON}            css=button[type="submit"]\n${SUCCESS_ALERT}            css=.alert-success\n${TURNSTILE_CONTAINER}      css=[data-sitekey]\n\n*** Test Cases ***\nScenario: Deterministic User Registration Behind Protected WAF\n    [Documentation]    Validates registration flow behind WAF allowlisting and passes Turnstile.\n    [Tags]             waf_protected    smoke\n    \n    Navigate To Target And Await Hydration    ${settings.base_url}/register\n    Fill Registration Credentials              automation-ci-agent@enterprise.internal\n    Assert Turnstile Test Challenge Passed\n    Submit Registration And Assert Success\n\n*** Keywords ***\nInitialize Enterprise Browser Context\n    [Documentation]    Launches headless browser and applies global HTTP WAF bypass headers.\n    New Browser\n    ...    browser=chromium\n    ...    headless=${settings.headless}\n    ...    args=["--no-sandbox", "--disable-dev-shm-usage", "--disable-gpu"]\n\n    New Context\n    ...    viewport={\'width\': 1920, \'height\': 1080}\n    ...    extraHTTPHeaders=${settings.waf_headers_dict}\n    ...    ignoreHTTPSErrors=True\n\nNavigate To Target And Await Hydration\n    [Arguments]    ${target_url}\n    [Documentation]    Navigates to URL and waits for DOM stabilization and spinner detachment.\n    New Page       ${target_url}\n    Wait For App Loader To Disappear    timeout=${settings.browser_timeout_ms}ms\n\nWait For App Loader To Disappear\n    [Arguments]    ${timeout}=30000ms\n    [Documentation]    Waits until the global loader spinner is detached from DOM or hidden.\n    Wait For Elements State\n    ...    selector=${SPINNER_LOCATOR}\n    ...    state=detached\n    ...    timeout=${timeout}\n\nFill Registration Credentials\n    [Arguments]    ${email}\n    Wait For Elements State    selector=${REGISTRATION_FORM}    state=visible\n    Fill Text                  selector=${EMAIL_INPUT}           txt=${email}\n\nAssert Turnstile Test Challenge Passed\n    [Documentation]    Verifies that the Turnstile container is present with the test sitekey.\n    Wait For Elements State    selector=${TURNSTILE_CONTAINER}    state=attached\n    Get Attribute              selector=${TURNSTILE_CONTAINER}    attribute=data-sitekey    ==    ${settings.turnstile_always_passes_sitekey}\n\nSubmit Registration And Assert Success\n    Click                      selector=${SUBMIT_BUTTON}\n    Wait For App Loader To Disappear\n    Wait For Elements State    selector=${SUCCESS_ALERT}         state=visible\n')
    create_file('tests/test_selenium.py', '"""\ntests/test_selenium.py\nPure Python pytest module implementing Selenium 4 with CDP header injection\nand explicit WebDriverWait element sync strategies.\n"""\n\nfrom typing import Generator\nimport pytest\nfrom selenium import webdriver\nfrom selenium.webdriver.chrome.service import Service\nfrom selenium.webdriver.chrome.options import Options\nfrom selenium.webdriver.common.by import By\nfrom selenium.webdriver.support.ui import WebDriverWait\nfrom selenium.webdriver.support import expected_conditions as EC\n\nfrom config.settings import settings\n\n\n@pytest.fixture(scope="function")\ndef driver() -> Generator[webdriver.Chrome, None, None]:\n    """\n    Initializes a headless Chrome session using modern Selenium 4 options,\n    injecting WAF bypass headers directly via Chrome DevTools Protocol (CDP).\n    """\n    chrome_options = Options()\n    if settings.headless:\n        chrome_options.add_argument("--headless=new")\n    \n    # Standard enterprise CI sandbox stability switches\n    chrome_options.add_argument("--no-sandbox")\n    chrome_options.add_argument("--disable-dev-shm-usage")\n    chrome_options.add_argument("--disable-gpu")\n    chrome_options.add_argument("--window-size=1920,1080")\n    chrome_options.add_argument("--ignore-certificate-errors")\n\n    service = Service()\n    chrome_driver = webdriver.Chrome(service=service, options=chrome_options)\n    \n    try:\n        # Inject custom WAF header via CDP Network domain\n        chrome_driver.execute_cdp_cmd("Network.enable", {})\n        chrome_driver.execute_cdp_cmd(\n            "Network.setExtraHTTPHeaders",\n            {"headers": settings.waf_headers_dict}\n        )\n        yield chrome_driver\n    finally:\n        # Guarantee teardown to prevent zombie chromium processes in CI agents\n        chrome_driver.quit()\n\n\n@pytest.mark.waf_protected\n@pytest.mark.regression\ndef test_authenticated_dashboard_load(driver: webdriver.Chrome) -> None:\n    """\n    Tests dashboard landing behind WAF allowlisting, verifying that the\n    application loading screen completely dissolves before checking components.\n    """\n    target_url = f"{settings.base_url}/dashboard"\n    driver.get(target_url)\n\n    wait = WebDriverWait(driver, timeout=settings.browser_timeout_ms / 1000.0)\n\n    # 1. Deterministic sync: Wait for the application overlay spinner to dissolve\n    loader_locator = (By.CSS_SELECTOR, "#app-loader")\n    wait.until(\n        EC.invisibility_of_element_located(loader_locator),\n        message=f"Application loader \'{loader_locator}\' failed to resolve within timeout."\n    )\n\n    # 2. Wait for main content container to hydrate into active DOM\n    main_container = wait.until(\n        EC.visibility_of_element_located((By.CSS_SELECTOR, "main[role=\'main\'], div.dashboard-root")),\n        message="Main dashboard view failed to render after loader resolution."\n    )\n\n    # 3. Assert state without thread sleeps\n    assert main_container.is_displayed(), "Dashboard container must be visible to the user."\n    assert "Dashboard" in driver.title, f"Unexpected page title: {driver.title}"\n')

