    def get_rag_blueprint_prompt(self, max_scenarios: int = 8) -> str:
        """
        Synthesizes grounded test scenarios, verified DOM selectors, and page topologies
        into a structured prompt blueprint for the LLM test generator.
        """
        scenarios = self.build_test_scenarios()
        selected_scenarios = scenarios[:max_scenarios]
        
        blueprint_lines = [
            "--- RAG-GROUNDED TEST BLUEPRINT & REAL DOM SELECTORS ---",
            f"Target Application: {self.target_url}",
            f"Discovered Routes: {len(self.indexed_pages)} pages crawled",
            ""
        ]
        
        blueprint_lines.append("### 1. MULTI-TIER PERSONA SPECIFICATIONS & AUDITABLE PROCEDURES (MANUAL TESTER -> PO -> PM)")
        blueprint_lines.append("STRICT CONTRACT: Every test case must follow Arrange-Act-Assert with explicit pre-conditions, interaction validations, and state mutations.")
        for s in selected_scenarios:
            blueprint_lines.append(f"- Scenario [{s['id']}] {s['title']} | Priority: {s['priority']} | Trace: {s['req_id']}")
            blueprint_lines.append(f"    * Precondition: Verify target element is interactable and URL is reachable")
            for st in s.get("steps", []):
                blueprint_lines.append(f"    * Execution Step: {st}")
            blueprint_lines.append(f"    * State Assertion: Verify DOM mutation, non-zero element values, and absence of 500 error boundaries")
            blueprint_lines.append(f"    * Audit Milestone: Log explicit confirmation step into Allure/Pabot reports")
        
        blueprint_lines.append("")
        blueprint_lines.append("DISCOVERED VERIFIED PAGE DOM ELEMENTS (USE REAL SELECTORS ONLY):")
        for p in self.indexed_pages[:6]:
            p_name = p.get("name", "Page")
            p_url = p.get("url", "")
            inputs = p.get("inputs", [])
            buttons = p.get("buttons", [])
            dropdowns = p.get("dropdowns", [])
            images = p.get("verified_images", [])
            forms = p.get("verified_forms", [])
            tables = p.get("verified_tables", [])
            catalogs = p.get("verified_catalogs", [])
            blueprint_lines.append(f"Page [{p_name}] ({p_url}):")
            if forms:
                blueprint_lines.append(f"  Forms: {', '.join([f['selector'] + ' (' + f['purpose'] + ')' for f in forms[:3]])}")
            if catalogs:
                blueprint_lines.append(f"  Catalog Cards: {', '.join([c['selector'] + ' (' + c['title'] + ')' for c in catalogs[:3]])}")
            if tables:
                blueprint_lines.append(f"  Tables: {', '.join([t['selector'] for t in tables[:2]])}")
            if inputs:
                blueprint_lines.append(f"  Inputs: {', '.join(inputs[:4])}")
            if buttons:
                blueprint_lines.append(f"  Buttons: {', '.join(buttons[:4])}")
            if dropdowns:
                blueprint_lines.append(f"  Dropdowns: {', '.join(dropdowns[:3])}")
            if images:
                blueprint_lines.append(f"  Images: {', '.join([img['selector'] for img in images[:4]])}")
        
        blueprint_lines.append("---------------------------------------------------------")
        return "\n".join(blueprint_lines)

