"""

def generate_guaranteed_robot_suite(target_url, username, password, page_manifest, apis):
    base_url = str(target_url).rstrip('/')
    rag = QAContextRAGEngine(target_url, page_manifest, apis)
    scenarios = rag.build_test_scenarios()
    
    dynamic_ui_tests = ""
    for s in scenarios:
        steps_code = "\n".join([f"    {st}" for st in s['steps']])
        dynamic_ui_tests += f"""
