@app.post("/api/system/apply_llm_settings")
def api_apply_llm_settings(payload: ApplyLLMSettingsPayload):
    try:
        cfg = payload.dict()
        cfg["applied_at"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        saved = save_active_llm_config(cfg)
        
        # Evict old runner to force fresh context instantiation
        evict_ollama_model(payload.model)
        time.sleep(0.3)
        
        # Pre-warm with calibrated context
        pre_warm_ollama_model(payload.model, scaled_ctx=payload.num_ctx)
        
        # Sync global concurrency to Redis
        try:
            import redis as py_redis
            r = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
            r.set("mcp_global_concurrency", payload.concurrency)
        except: pass
        
        return {
            "status": "success",
            "message": f"Applied '{payload.profile_name}' successfully ({payload.num_ctx} Ctx, {payload.num_batch} Batch, 100% GPU). Active for Runs and Project Chat.",
            "config": saved
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

