def _resolve_active_project_url(explicit_url: Optional[str] = None) -> str:
    """Resolves the current project website URL from payload, session, or crawl manifest. Excludes localhost."""
    try:
        from .engines.vector_dom_engine import DOMVectorEngine
    except ImportError:
        from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine

    if explicit_url and not DOMVectorEngine.is_disallowed_url(explicit_url):
        return explicit_url.strip()

    # 1. Pipeline session
    session_file = "artifacts/logs/pipeline_session.json"
    if os.path.exists(session_file):
        try:
            with open(session_file, "r", encoding="utf-8") as f:
                sess = json.load(f)
                u = sess.get("url", "")
                if u and not DOMVectorEngine.is_disallowed_url(u):
                    return u.strip()
        except Exception:
            pass

    # 2. Page manifest
    manifest_file = "artifacts/reports/page_manifest.json"
    if os.path.exists(manifest_file):
        try:
            with open(manifest_file, "r", encoding="utf-8") as f:
                manifest = json.load(f)
                if isinstance(manifest, list):
                    for item in manifest:
                        u = item.get("url", "")
                        if u and not DOMVectorEngine.is_disallowed_url(u):
                            return u.strip()
        except Exception:
            pass

    # 3. Task status
    status_file = "artifacts/logs/task_status.json"
    if os.path.exists(status_file):
        try:
            with open(status_file, "r", encoding="utf-8") as f:
                ts = json.load(f)
                u = ts.get("url", "")
                if u and not DOMVectorEngine.is_disallowed_url(u):
                    return u.strip()
        except Exception:
            pass

    return ""

@app.get("/api/dom/elements")
def api_get_dom_elements(route: Optional[str] = None, target_url: Optional[str] = None):
    try:
        try:
            from .engines.vector_dom_engine import DOMVectorEngine
        except ImportError:
            from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine
        v_engine = DOMVectorEngine(".")
        
        # If explicit target_url was provided and is disallowed (e.g. localhost:8000), immediately return empty elements
        if target_url and v_engine.is_disallowed_url(target_url):
            return {
                "status": "success",
                "target_url": target_url,
                "count": 0,
                "elements": [],
                "routes": ["All"]
            }

        project_url = _resolve_active_project_url(target_url)
        if not project_url or v_engine.is_disallowed_url(project_url):
            return {
                "status": "success",
                "target_url": "",
                "count": 0,
                "elements": [],
                "routes": ["All"]
            }

        # Strictly filter by project website URL domain; NO preseeded localhost data at any time
        elements = v_engine.get_elements_by_url(target_url=project_url, route=route)

        # Discovered routes strictly for this project website
        all_project_elements = v_engine.get_elements_by_url(target_url=project_url, route=None)
        discovered_routes = set(["All", "/"])
        for el in all_project_elements:
            r = el.get("page_route") or el.get("route")
            if r:
                discovered_routes.add(r)
        
        # Also include any routes from page_manifest for this domain
        manifest_file = "artifacts/reports/page_manifest.json"
        if os.path.exists(manifest_file) and project_url:
            try:
                from urllib.parse import urlparse
                p_clean = project_url if project_url.startswith(('http://', 'https://')) else 'https://' + project_url
                p_domain = urlparse(p_clean).netloc.replace("www.", "").lower()
                with open(manifest_file, "r", encoding="utf-8") as f:
                    manifest = json.load(f)
                    for item in manifest:
                        u = item.get("url", "")
                        if u:
                            u_clean = u if u.startswith(('http://', 'https://')) else 'https://' + u
                            u_domain = urlparse(u_clean).netloc.replace("www.", "").lower()
                            if u_domain == p_domain:
                                r = urlparse(u_clean).path or "/"
                                discovered_routes.add(r)
            except Exception:
                pass

        sorted_routes = ["All"] + sorted([r for r in discovered_routes if r != "All"])

        return {
            "status": "success",
            "target_url": project_url,
            "count": len(elements),
            "elements": elements,
            "routes": sorted_routes
        }
    except Exception as e:
        return {"status": "error", "message": str(e), "elements": [], "routes": ["All"]}

@app.post("/api/dom/index")
def api_index_dom(payload: DOMIndexPayload):
    try:
        try:
            from .engines.vector_dom_engine import DOMVectorEngine
        except ImportError:
            from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine
        v_engine = DOMVectorEngine(".")
        if payload.url and v_engine.is_disallowed_url(payload.url):
            return {"status": "error", "message": "Target URL cannot be localhost or loopback (preseeded data is disabled)."}

        html = payload.html or payload.html_content
        target_url = _resolve_active_project_url(payload.url or payload.route)
        if not target_url or v_engine.is_disallowed_url(target_url):
            return {"status": "error", "message": "Target URL must be a valid external project website URL (preseeded localhost data is disabled)."}
        
        if not html:
            import requests
            headers = {
                "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"
            }
            res = requests.get(target_url, headers=headers, timeout=10, verify=False)
            html = res.text
            
        indexed = v_engine.index_page_dom(html, target_url)
        return {
            "status": "success",
            "indexed_count": len(indexed),
            "url": target_url
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

@app.post("/api/locators/heal")
def api_heal_locator(payload: LocatorHealPayload):
    try:
        try:
            from .engines.vector_dom_engine import DOMVectorEngine
        except ImportError:
            from aspice_qa_framework.engines.vector_dom_engine import DOMVectorEngine
        v_engine = DOMVectorEngine(".")
        res = v_engine.heal_broken_locator(
            broken_locator=payload.broken_locator,
            error_trace=payload.error_trace or "",
            current_dom=payload.dom_snippet or "",
            page_route=payload.route or "/"
        )
        healed_bool = res.get("status") == "HEALED"
        best_loc = res.get("best_healed_wdio") or res.get("best_healed_locator")
        top_suggestion = (res.get("suggestions") or [{}])[0]
        spatial_box = top_suggestion.get("spatial_location")
        candidates = [
            {
                "tag": s.get("target_tag"),
                "selector": s.get("suggested_wdio") or s.get("suggested_locator"),
                "text": s.get("target_text"),
                "similarity_score": int(s.get("confidence", 0) * 100)
            }
            for s in res.get("suggestions", [])
        ]
        return {
            **res,
            "status": "success",
            "healing_status": res.get("status"),
            "healed": healed_bool,
            "confidence": int(res.get("confidence", 0) * 100),
            "broken_locator": res.get("original_locator") or payload.broken_locator,
            "healed_locator": best_loc,
            "spatial_coordinates": spatial_box,
            "candidates": candidates,
            "healing": res
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

