@app.get("/api/diagnostics")
def run_preflight_diagnostics():
    auto_cleanup_routine()
    cfg = {}
    
    sock_path = "/var/run/docker.sock"
    if os.path.exists(sock_path) and os.access(sock_path, os.R_OK):
        cfg["Docker Socket"] = {"status": "ONLINE", "crit": True, "detail": "Mounted & Accessible"}
    else:
        cfg["Docker Socket"] = {"status": "ERROR", "crit": True, "detail": "Missing Socket Mount"}

    try:
        r = redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        if r.ping():
            cfg["Redis Broker"] = {"status": "ONLINE", "crit": True, "detail": "Connected & Healthy"}
    except Exception as e:
        cfg["Redis Broker"] = {"status": "ERROR", "crit": True, "detail": str(e)}

    try:
        socket.setdefaulttimeout(2)
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(("postgres", 5432))
        cfg["PostgreSQL DB"] = {"status": "ONLINE", "crit": True, "detail": "Port 5432 Open"}
    except Exception as e:
        cfg["PostgreSQL DB"] = {"status": "ERROR", "crit": True, "detail": "Unreachable"}

    try:
        socket.setdefaulttimeout(2)
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(("8.8.8.8", 53))
        cfg["External Network"] = {"status": "ONLINE", "crit": False, "detail": "Internet Reachable"}
    except:
        cfg["External Network"] = {"status": "WARNING", "crit": False, "detail": "No Internet Access"}

    celery_active = False
    try:
        inspect = celery_app.control.inspect(timeout=1.0)
        active_nodes = inspect.ping() if inspect else None
        if active_nodes:
            cfg["Compute Engine"] = {"status": "ONLINE", "crit": True, "detail": f"Celery Active ({len(active_nodes)} node(s))"}
            celery_active = True
    except: pass
    if not celery_active: cfg["Compute Engine"] = {"status": "ONLINE", "crit": True, "detail": "In-Process ThreadPool Active"}

    ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate").replace("/api/generate", "/api/tags")
    try: 
        res = requests.get(ollama_url, timeout=3)
        if res.status_code == 200: cfg["LLM Router"] = {"status": "ONLINE", "crit": True, "detail": "Ollama DeepSeek Ready"}
        else: cfg["LLM Router"] = {"status": "ERROR", "crit": True, "detail": f"HTTP {res.status_code}"}
    except Exception as e: cfg["LLM Router"] = {"status": "OFFLINE", "crit": True, "detail": str(e)}

    k6 = shutil.which("k6"); cfg["k6 Engine"] = {"status": "OK" if k6 else "MISSING", "crit": True, "detail": "Installed if k6 else Missing"}
    pabot = shutil.which("pabot"); cfg["Parallel Engine (Pabot)"] = {"status": "OK" if pabot else "MISSING", "crit": True, "detail": "Installed" if pabot else "Missing"}
    allure = shutil.which("allure"); cfg["Allure Reporter"] = {"status": "OK" if allure else "MISSING", "crit": True, "detail": "Installed" if allure else "Missing"}

    healthy = not any(v["status"] not in ["OK", "ONLINE"] and v["crit"] for v in cfg.values())
    return {"overall": "HEALTHY" if healthy else "ERROR", "config": cfg}

@app.post("/api/diagnostics/target")
def check_target_health(payload: TargetHealthPayload):
    import time
    try:
        start = time.time()
        res = requests.get(payload.url, timeout=10, verify=False)
        elapsed = round((time.time() - start) * 1000)
        if res.status_code < 400:
            return {"status": "ONLINE", "detail": f"HTTP {res.status_code} ({elapsed}ms)"}
        else:
            return {"status": "WARNING", "detail": f"HTTP {res.status_code} ({elapsed}ms)"}
    except requests.exceptions.Timeout:
        return {"status": "ERROR", "detail": "Timeout (>10s)"}
    except Exception as e:
        return {"status": "ERROR", "detail": "Connection Refused"}

@app.post("/api/diagnostics/nist")
def check_nist_compliance(payload: NISTPayload):
    import requests
    import urllib.parse
    # Extract primary keyword from tech stack (e.g., 'React' from 'React / Node')
    keyword = urllib.parse.quote(payload.stack.split()[0] if payload.stack else "web")
    try:
        # NVD API 2.0 with a small timeout, max 5 results for fast check
        res = requests.get(f"https://services.nvd.nist.gov/rest/json/cves/2.0?keywordSearch={keyword}&resultsPerPage=5", timeout=7, verify=False)
        if res.status_code == 200:
            data = res.json()
            total_vulns = data.get("totalResults", 0)
            cves = []
            highest_severity = "LOW"
            severity_order = {"LOW": 1, "MEDIUM": 2, "HIGH": 3, "CRITICAL": 4}
            for vuln in data.get("vulnerabilities", []):
                cve = vuln.get("cve", {})
                cve_id = cve.get("id", "UNKNOWN")
                metrics = cve.get("metrics", {})
                cvss_data = metrics.get("cvssMetricV31", metrics.get("cvssMetricV30", []))
                base_severity = "UNKNOWN"
                if cvss_data and len(cvss_data) > 0:
                    base_severity = cvss_data[0].get("cvssData", {}).get("baseSeverity", "UNKNOWN")
                cves.append({"id": cve_id, "severity": base_severity})
                if base_severity in severity_order and severity_order[base_severity] > severity_order.get(highest_severity, 0):
                    highest_severity = base_severity
            
            status = "DANGER" if highest_severity in ["HIGH", "CRITICAL"] else "WARNING" if total_vulns > 0 else "SECURE"
            return {"status": status, "total_vulns": total_vulns, "highest_severity": highest_severity, "cves": cves}
        else:
            return {"status": "ERROR", "detail": f"NVD HTTP {res.status_code}"}
    except requests.exceptions.Timeout:
        return {"status": "TIMEOUT", "detail": "NIST NVD API Timeout"}
    except Exception as e:
        return {"status": "ERROR", "detail": str(e)}

