@app.post("/api/project/import")
async def import_project(file: UploadFile = File(...)):
    try:
        import shutil, zipfile, os
        artifacts_dir = "artifacts"
        if os.path.exists(artifacts_dir):
            shutil.rmtree(artifacts_dir)
        os.makedirs(artifacts_dir, exist_ok=True)
        
        zip_path = os.path.join(artifacts_dir, "uploaded_project.zip")
        with open(zip_path, "wb") as buffer:
            shutil.copyfileobj(file.file, buffer)
            
        with zipfile.ZipFile(zip_path, 'r') as zip_ref:
            zip_ref.extractall(artifacts_dir)
            
        os.remove(zip_path)
        return {"status": "success", "message": "Project imported successfully."}
    except Exception as e:
        from fastapi.responses import JSONResponse
        return JSONResponse(status_code=500, content={"error": str(e)})

from fastapi.responses import StreamingResponse
import json

@app.post("/api/project/chat")
async def project_chat(req: ChatRequest):
    import os, json, requests
    
    # Gather context
    context = []
    if os.path.exists("artifacts/reports/page_manifest.json"):
        try:
            with open("artifacts/reports/page_manifest.json", "r") as f:
                context.append(f"PAGE MANIFEST:\n{f.read()}")
        except: pass
    if os.path.exists("artifacts/reports/Master_Requirements_Document.md"):
        try:
            with open("artifacts/reports/Master_Requirements_Document.md", "r") as f:
                context.append(f"BRD & STRATEGY:\n{f.read()}")
        except: pass
            
    scripts_dir = "artifacts/scripts"
    if os.path.exists(scripts_dir):
        for fname in os.listdir(scripts_dir):
            if fname.endswith((".py", ".js", ".robot", ".md")):
                try:
                    with open(os.path.join(scripts_dir, fname), "r", encoding="utf-8") as f:
                        context.append(f"SCRIPT: {fname}\n```\n{f.read()}\n```")
                except: pass
                    
    combined_context = "\n\n".join(context)[:30000] # Truncate to avoid context limits
    
    system_prompt = f"""You are an expert SDET and QA Architect. You have access to the user's current project artifacts.
Respond to their queries intelligently. If the user asks to fix or enhance a script or document, you MUST output the updated file contents inside a markdown code block preceded by a magic header:
# FILE: <filename.ext>
```
<full updated code here>
```
If you do this, the system will automatically overwrite the file.

### CURRENT PROJECT CONTEXT:
{combined_context}
"""
    
    ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate")
    vram_req = probe_and_scale_vram_resources("deepseek-r1:1.5b")
    payload = {
        "model": "deepseek-r1:1.5b",
        "prompt": system_prompt + f"\n\nUSER MESSAGE: {req.message}",
        "stream": True,
        "options": {
            "temperature": 0.0,
            "top_p": 0.1,
            "top_k": 10,
            "repeat_penalty": 1.0,
            "num_ctx": vram_req.get("scaled_ctx", 8192),
            "num_gpu": -1,
            "use_mmap": True
        }
    }
    
    def generate():
        try:
            response = requests.post(ollama_url, json=payload, stream=True, timeout=60)
            for line in response.iter_lines():
                if line:
                    decoded = line.decode('utf-8')
                    try:
                        chunk = json.loads(decoded)
                        if "response" in chunk:
                            yield chunk["response"]
                    except: pass
        except Exception as e:
            yield f"Error connecting to LLM: {str(e)}"
            
    return StreamingResponse(generate(), media_type="text/plain")


