def get_allure_binary():
    """Robust binary resolver: checks local environment first, then verified cached builds, with multi-mirror standalone fallback."""
    import shutil, subprocess, tarfile, urllib.request, platform

    is_windows = platform.system().lower() == "windows"
    bin_name = "allure.bat" if is_windows else "allure"

    # 1. Local PATH and common system locations check
    candidate_paths = [
        shutil.which("allure"),
        "/usr/local/bin/allure",
        "/usr/bin/allure",
        os.path.expanduser("~/.npm-global/bin/allure")
    ]
    for candidate in candidate_paths:
        if candidate and os.path.exists(candidate):
            try:
                res = subprocess.run([candidate, "--version"], capture_output=True, text=True, timeout=5)
                if res.returncode == 0:
                    return candidate
            except Exception:
                pass

    # 2. Local project artifacts cache check
    standalone_dir = os.path.abspath("artifacts/allure-2.24.1")
    standalone_bin = os.path.join(standalone_dir, "bin", bin_name)
    if os.path.exists(standalone_bin):
        try:
            if not is_windows:
                os.chmod(standalone_bin, 0o755)
            res = subprocess.run([standalone_bin, "--version"], capture_output=True, text=True, timeout=5)
            if res.returncode == 0:
                return standalone_bin
        except Exception:
            pass

    # 3. Robust Standalone Download Fallback (Multi-Mirror with Timeout)
    print("[ATP] No verified local Allure CLI found. Initializing standalone setup...")
    os.makedirs("artifacts", exist_ok=True)
    tgz_path = os.path.abspath("artifacts/allure-2.24.1.tgz")

    mirrors = [
        "https://repo.maven.apache.org/maven2/io/qameta/allure/allure-commandline/2.24.1/allure-commandline-2.24.1.tgz",
        "https://github.com/allure-framework/allure2/releases/download/2.24.1/allure-2.24.1.tgz"
    ]

    req_headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36"}
    downloaded = False

    for mirror_url in mirrors:
        try:
            req = urllib.request.Request(mirror_url, headers=req_headers)
            with urllib.request.urlopen(req, timeout=25) as response, open(tgz_path, "wb") as out_file:
                shutil.copyfileobj(response, out_file)
            if os.path.exists(tgz_path) and os.path.getsize(tgz_path) > 1000000:
                with tarfile.open(tgz_path, "r:gz") as tar:
                    tar.extractall(path="artifacts/")
                downloaded = True
                break
        except Exception as ex:
            print(f"[ATP WARN] Mirror failed ({mirror_url}): {ex}")
        finally:
            if os.path.exists(tgz_path):
                try: os.remove(tgz_path)
                except Exception: pass

    if downloaded and os.path.exists(standalone_bin):
        try:
            if not is_windows:
                os.chmod(standalone_bin, 0o755)
            return standalone_bin
        except Exception:
            pass

    return "allure"

def deduplicate_allure_results(allure_dir: str) -> int:
    """
    Ensures test reruns update existing results in-place rather than creating redundant test entries.
    Scans all *-result.json files, groups them by test identity (fullName or name),
    and retains ONLY the newest execution result (highest stop/start timestamp),
    removing older obsolete execution result files.
    """
    if not os.path.exists(allure_dir):
        return 0
    import glob, json
    result_files = glob.glob(os.path.join(allure_dir, "*-result.json"))
    by_test = {}
    for rf in result_files:
        try:
            with open(rf, "r", encoding="utf-8") as f:
                data = json.load(f)
            test_key = data.get("name") or data.get("fullName")
            if not test_key:
                continue
            timestamp = data.get("stop") or data.get("start") or os.path.getmtime(rf)
            by_test.setdefault(test_key, []).append((timestamp, rf))
        except Exception:
            pass

    deleted_count = 0
    for test_key, entries in by_test.items():
        if len(entries) > 1:
            entries.sort(key=lambda x: x[0])
            for _, old_file in entries[:-1]:
                try:
                    os.remove(old_file)
                    deleted_count += 1
                except Exception:
                    pass
    return deleted_count

@app.post("/api/reports/allure/generate")
def generate_allure_report(payload: dict = None):
    """Robust generator supporting historical swaps, trend injection, and single-file mode."""
    if payload is None: payload = {}
    run_id = payload.get("run_id", "latest")
    include_trends = payload.get("include_trends", True)
    single_file = payload.get("single_file", False)

    try:
        results_dir = os.path.abspath(os.path.join("artifacts", "reports", "allure-results"))
        report_dir = os.path.abspath(os.path.join("artifacts", "reports", "allure-report"))
        
        # In-place deduplication of rerun results before report compilation
        deduplicate_allure_results(results_dir)
        
        # 1. Swap in historical data if requested
        if run_id != "latest":
            run_dir = os.path.abspath(os.path.join("artifacts", "reports", "history", run_id))
            if os.path.exists(run_dir):
                shutil.rmtree(results_dir, ignore_errors=True)
                shutil.copytree(run_dir, results_dir, dirs_exist_ok=True)
                deduplicate_allure_results(results_dir)
        
        os.makedirs(results_dir, exist_ok=True)
        os.makedirs(report_dir, exist_ok=True)
        
        # 2. Inject Historical Trends
        if include_trends:
            old_history = os.path.join(report_dir, "history")
            new_history = os.path.join(results_dir, "history")
            if os.path.exists(old_history):
                shutil.copytree(old_history, new_history, dirs_exist_ok=True)
        
        # 3. Execute Standalone Allure Generation
        allure_exe = get_allure_binary()
        cmd = f"{allure_exe} generate {results_dir} -o {report_dir} --clean"
        result = subprocess.run(cmd, shell=True, capture_output=True, text=True)
        
        # 3.5. Safely handle Single-File bundling using npx
        if single_file and result.returncode == 0:
            subprocess.run(f"npx -y allure-single-html-file {report_dir}", shell=True, capture_output=True, text=True)
            if os.path.exists("complete.html"):
                shutil.move("complete.html", os.path.join(report_dir, "index.html"))
        
        # 4. HTML Fallback Dashboard (If Allure CLI fails)
        html_file = os.path.join(report_dir, "index.html")
        java_found = shutil.which("java") is not None

        if result.returncode != 0 or not os.path.exists(html_file) or os.path.getsize(html_file) < 100:
            stdout_msg = (result.stdout or "None").replace('\n', '<br>')
            stderr_msg = (result.stderr or "None").replace('\n', '<br>')
            java_status = "<span style='color:#22c55e;'>DETECTED</span>" if java_found else "<span style='color:#ef4444;'>MISSING (Allure requires OpenJDK/JRE)</span>"

            html_content = f"""<!DOCTYPE html><html><head><meta charset="utf-8"><title>Allure Report Diagnostic</title></head>
            <body style="background:#0a0f1d; color:#e2e8f0; font-family:monospace; padding:30px;">
                <div style="max-width:900px; margin:0 auto; background:#111827; border:1px solid #374151; border-radius:8px; padding:24px;">
                    <h2 style="color:#f87171; margin-top:0;">⚠️ Allure CLI Compilation Fault (Run: {run_id})</h2>
                    <p style="color:#9ca3af; font-size:13px;">Binary Executable: <b>{allure_exe}</b> | Java Runtime: {java_status}</p>
                    <div style="background:#030712; border:1px solid #1f2937; border-radius:6px; padding:12px; margin-top:16px; font-size:12px; overflow-x:auto;">
                        <b style="color:#93c5fd;">STDOUT:</b><br><pre style="color:#e5e7eb; margin:4px 0 12px 0;">{stdout_msg}</pre>
                        <b style="color:#fca5a5;">STDERR:</b><br><pre style="color:#f87171; margin:4px 0 0 0;">{stderr_msg}</pre>
                    </div>
                    <div style="margin-top:16px; font-size:12px; color:#9ca3af;">
                        💡 <b>Diagnostic Advice:</b> Ensure <code>artifacts/reports/allure-results</code> contains valid test outputs and Java JRE is accessible on <code>PATH</code>.
                    </div>
                </div>
            </body></html>"""
            with open(html_file, "w", encoding="utf-8") as f:
                f.write(html_content)

        return {"status": "success", "message": f"Allure Report Generated (Run: {run_id})"}
    except Exception as e:
        return {"status": "error", "message": f"Allure generation failed: {str(e)}"}

@app.get("/api/reports/allure/html/{file_path:path}")
@app.get("/api/reports/allure/html")
@app.get("/api/reports/allure/{file_path:path}")
def get_allure_assets(request: Request, file_path: str = ""):
    """Dynamically serves all Allure assets and auto-corrects relative browser pathing errors."""
    from fastapi.responses import RedirectResponse, FileResponse, HTMLResponse, JSONResponse
    import mimetypes

    # 1. Protect other specific allure routes from being swallowed
    if file_path in ["download", "generate"]:
        return JSONResponse(status_code=404, content={"error": "Not an asset"})
        
    # 2. Force trailing slash redirect to fix browser relative pathing issues
    if str(request.url.path).endswith("/api/reports/allure/html"):
        params = request.url.query
        redirect_url = "/api/reports/allure/html/index.html"
        if params: redirect_url += f"?{params}"
        return RedirectResponse(url=redirect_url)

    # 3. Clean up the requested path
    if file_path.startswith("html/"):
        file_path = file_path[5:]
    elif file_path == "html":
        file_path = "index.html"
        
    if not file_path:
        file_path = "index.html"
        
    base_dir = os.path.abspath(os.path.join("artifacts", "reports", "allure-report"))
    target_path = os.path.abspath(os.path.join(base_dir, file_path))
    
    # 4. Security check to prevent directory traversal
    if not os.path.normcase(target_path).startswith(os.path.normcase(base_dir)):
        return JSONResponse(status_code=403, content={"error": "Access Denied"})
        
    # 5. Handle missing files and auto-generation
    if not os.path.exists(target_path):
        if file_path == "index.html":
            generate_allure_report()
            if not os.path.exists(target_path):
                return HTMLResponse("<h2>Report not yet generated. Run a test pipeline first.</h2>")
        else:
            return JSONResponse(status_code=404, content={"error": f"Asset not found: {file_path}"})
            
    # 6. Return the file with explicit MIME type overrides to prevent Windows registry bugs
    ext = os.path.splitext(target_path)[1].lower()
    if ext == ".js": media_type = "application/javascript"
    elif ext == ".css": media_type = "text/css"
    elif ext == ".json": media_type = "application/json"
    elif ext == ".woff2": media_type = "font/woff2"
    elif ext == ".woff": media_type = "font/woff"
    elif ext == ".svg": media_type = "image/svg+xml"
    elif ext == ".html": media_type = "text/html"
    elif ext == ".png": media_type = "image/png"
    elif ext == ".csv": media_type = "text/csv"
    elif ext == ".txt": media_type = "text/plain"
    else:
        media_type, _ = mimetypes.guess_type(target_path)
        if not media_type:
            media_type = "application/octet-stream"
            
    response = FileResponse(target_path, media_type=media_type)
    response.headers["Cache-Control"] = "no-cache, no-store, must-revalidate"
    response.headers["Pragma"] = "no-cache"
    response.headers["Expires"] = "0"
    return response

@app.get("/api/pipeline/artifact/{step_id}")
def get_pipeline_artifact(step_id: str):
    import os
    artifact_map = {
        "step_1": "artifacts/reports/security_scan.json",
        "step_2": "artifacts/reports/page_manifest.json",
        "step_2_5": "artifacts/reports/Master_Requirements_Document.md",
        "step_3": "artifacts/logs/engine_trace.jsonl",
        "step_4": "artifacts/reports/raw_code.txt",
        "step_5": "artifacts/scripts/generated_test.robot",
        "step_6": "artifacts/reports/pabot_results/output.xml"
    }
    file_path = artifact_map.get(step_id)
    if not file_path or not os.path.exists(file_path):
        return JSONResponse(content={"content": "No artifact generated for this step yet."}, status_code=200)
    
    try:
        with open(file_path, "r", encoding="utf-8") as f:
            content = f.read()
            if len(content) > 50000:
                content = content[:50000] + "\n... [TRUNCATED - Payload too large to render in browser preview] ..."
            return JSONResponse(content={"content": content, "file": file_path}, status_code=200)
    except Exception as e:
        return JSONResponse(content={"error": str(e)}, status_code=500)
@app.get("/api/reports/allure/download")
def download_allure_report():
    report_dir = os.path.join("artifacts", "reports", "allure-report")
    if not os.path.exists(report_dir) or not os.path.exists(os.path.join(report_dir, "index.html")):
        generate_allure_report()
        
    zip_filename = "Allure_Quality_Report.zip"
    with zipfile.ZipFile(zip_filename, "w", zipfile.ZIP_DEFLATED) as zipf:
        if os.path.exists(report_dir):
            for root, _, files in os.walk(report_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    arcname = os.path.relpath(file_path, report_dir)
                    zipf.write(file_path, arcname)
    return FileResponse(zip_filename, media_type="application/zip", filename="Allure_Quality_Report.zip")


