@app.post("/api/generate")
def trigger_generation(cfg: GenConfig):
    global active_harness
    if active_harness:
        try: active_harness.stop()
        except: pass
        import time; time.sleep(1)
    nuke_all_resources()

    # Sync requested concurrency directly to Redis for active session
    try:
        import redis as py_redis
        r_sync = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        r_sync.set("mcp_global_concurrency", cfg.mcp_concurrency)
    except Exception:
        pass

    # Create the enhanced MCP harness and store globally for stop control
    active_harness = EnhancedMCPHarness(
        ollama_url=os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"),
        model_name=cfg.model_name,
        status_callback=lambda msg: print(msg),
        trace_callback=lambda *a: None,
        ctx_size=cfg.context_size,
        strategy=cfg.compute_strategy,
        concurrency=cfg.mcp_concurrency,
        temperature=cfg.temperature,
        max_tokens=cfg.max_tokens,
        chunk_threshold=int(cfg.context_size * 0.5)
    )

    for folder in ["artifacts/logs", "artifacts/scripts", "artifacts/screencast"]:
        shutil.rmtree(folder, ignore_errors=True)
        os.makedirs(folder, exist_ok=True)
        
    # Carefully clean reports without destroying historical archives
    os.makedirs("artifacts/reports", exist_ok=True)
    for sub in ["allure-results"]: # Leave allure-report intact so trends survive
        shutil.rmtree(f"artifacts/reports/{sub}", ignore_errors=True)
    
    with open("artifacts/logs/orchestrator.log", "w", encoding="utf-8") as f: 
        f.write("=== [ORCHESTRATOR STARTED] Master Session Initialized ===\n")
        f.flush()
        
    init_entry = {
        "time": datetime.now().strftime("%H:%M:%S.%f")[:-3],
        "cat": "DAEMON_STATUS",
        "msg": f"Target initiated: {cfg.url} [Mode: {cfg.execution_mode.upper()}], Model: {cfg.model_name}, Stack: {cfg.selected_stack}, Workers: {cfg.mcp_concurrency}",
        "elapsed": 0, "inference": 0, "tokens": 0, "speed": 0
    }
    with open("artifacts/logs/engine_trace.jsonl", "w", encoding="utf-8") as f:
        f.write(json.dumps(init_entry) + "\n")
        f.flush()
    
    init_steps = {
        "step_1": {"name": "1. Recon & CVE", "status": "PENDING", "required": True},
        "step_2": {"name": "2. Auth & Spider", "status": "PENDING", "required": True},
        "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
        "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
        "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
        "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
    }
    
    import time
    with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f:
        json.dump({
            "status": "processing", 
            "progress": 5, 
            "steps": init_steps, 
            "current_task": f"Initializing Engine in {cfg.execution_mode.upper()} Mode", 
            "current_command": "Spawning Celery process...", 
            "chunking": False,
            "start_time": time.time()
        }, f)
    
    # 1. Safely extract the dictionary supporting both Pydantic V1 and V2
    try:
        cfg_data = cfg.model_dump()
    except AttributeError:
        cfg_data = cfg.dict()

    # Retain all user selected parameters in cache file and Redis
    try:
        os.makedirs("artifacts/logs", exist_ok=True)
        with open("artifacts/logs/cached_user_params.json", "w", encoding="utf-8") as f:
            json.dump(cfg_data, f, indent=4)
        import redis as py_redis
        r_param = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        r_param.set("cached_user_params", json.dumps(cfg_data))
    except Exception:
        pass

    # 2. Attempt Celery dispatch, fallback to in-process ThreadPool if Celery is offline
    try:
        generate_artifacts_task.delay(cfg_data)
    except Exception as e:
        print(f"[WARNING] Celery dispatch failed ({e}). Falling back to in-process execution.")
        in_process_pool.submit(run_e2e_pipeline_core, cfg_data)
        
    return {"status": "processing"}

# ⚡ PIPELINE PAUSE & CONTINUE ENDPOINTS ⚡
@app.post("/api/pipeline/pause")
def pause_pipeline():
    """Cleanly pauses the running pipeline, saves intermediate state and crawled data,
    detaches browser processes safely, and marks can_continue: True."""
    global active_harness
    try:
        import redis as py_redis
        r = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        r.set("pipeline_paused", 1)
    except Exception:
        pass

    if active_harness:
        try: active_harness.stop()
        except Exception: pass

    status_file = "artifacts/logs/task_status.json"
    curr_state = {}
    if os.path.exists(status_file):
        try:
            with open(status_file, "r", encoding="utf-8") as f:
                curr_state = json.load(f)
        except Exception:
            curr_state = {}

    curr_state["status"] = "paused"
    curr_state["can_continue"] = True
    curr_state["current_task"] = "Pipeline Paused by User (Intermediate State Preserved)"
    curr_state["current_command"] = "Paused cleanly. Click Continue Execution to resume."
    try:
        with open(status_file, "w", encoding="utf-8") as f:
            json.dump(curr_state, f, indent=4)
    except Exception:
        pass

    # Snapshot latest run tokens and clean up browser instances cleanly
    try:
        snapshot_latest_run_tokens(status="paused")
        execute_post_run_cleanup(preserve_tokens=True, run_status="paused")
    except Exception:
        pass

    timestamp = datetime.now().strftime("%H:%M:%S.%f")[:-3]
    trace_entry = {
        "time": timestamp,
        "cat": "DAEMON_STATUS",
        "msg": "⏸️ PIPELINE PAUSED: Intermediate state, DOM vectors, and token metrics retained. Ready to resume.",
        "elapsed": 0, "inference": 0, "tokens": 0, "speed": 0
    }
    try:
        with open("artifacts/logs/engine_trace.jsonl", "a", encoding="utf-8") as f:
            f.write(json.dumps(trace_entry) + "\n")
    except Exception:
        pass

    return {"status": "paused", "can_continue": True, "message": "Pipeline paused cleanly."}

@app.post("/api/pipeline/resume")
@app.post("/api/pipeline/continue")
def resume_pipeline(payload: Optional[ResumePayload] = None):
    global active_harness
    if active_harness:
        try: active_harness.stop()
        except: pass
        import time; time.sleep(1)

    # Clear pause flag in Redis
    try:
        import redis as py_redis
        r_sync = py_redis.Redis.from_url(os.environ.get("REDIS_URL", "redis://redis:6379/0"))
        r_sync.delete("pipeline_paused")
        if payload and payload.mcp_concurrency:
            r_sync.set("mcp_global_concurrency", payload.mcp_concurrency)
    except Exception:
        pass
        
    try:
        path = "artifacts/logs/engine_trace.jsonl"
        if os.path.exists(path):
            open(path, "w", encoding="utf-8").close()
    except Exception:
        pass
    
    def resume_task_worker():
        try:
            with open("artifacts/logs/pipeline_session.json", "r", encoding="utf-8") as f:
                sess = json.load(f)
            
            cached_params = {}
            if os.path.exists("artifacts/logs/cached_user_params.json"):
                try:
                    with open("artifacts/logs/cached_user_params.json", "r", encoding="utf-8") as cf:
                        cached_params = json.load(cf)
                except Exception:
                    pass

            with open("artifacts/logs/task_status.json", "r", encoding="utf-8") as f:
                curr_state = json.load(f)
            
            steps = curr_state.get("steps", {
                "step_1": {"name": "1. Recon & CVE", "status": "COMPLETED", "required": True},
                "step_2": {"name": "2. Auth & Spider", "status": "COMPLETED", "required": True},
                "step_3": {"name": "3. MCP Synthesis", "status": "PENDING", "required": True},
                "step_4": {"name": "4. SDET Validation", "status": "PENDING", "required": True},
                "step_5": {"name": "5. Assembly", "status": "PENDING", "required": True},
                "step_6": {"name": "6. Pabot Parallel", "status": "PENDING", "required": False}
            })
            
            # Update status to processing
            curr_state["status"] = "processing"
            curr_state["can_continue"] = False
            curr_state["current_task"] = "Resuming Synthesis & Assembly Pipeline..."
            with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f:
                json.dump(curr_state, f, indent=4)

            engine = AICoreEngine(None, os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/generate"))
            dom_pages = sess.get("dom_pages", [])
            
            # Resolve parameters, prioritizing payload then cached_params then session
            model_name = (payload.model_name if payload and payload.model_name else None) or cached_params.get("model_name") or sess.get("model_name", "deepseek-r1:1.5b")
            ctx_size = (payload.context_size if payload and payload.context_size else None) or cached_params.get("context_size") or sess.get("context_size", 8192)
            compute_strategy = (payload.compute_strategy if payload and payload.compute_strategy else None) or cached_params.get("compute_strategy") or sess.get("compute_strategy", "Smart Auto-Offload")
            concurrency = (payload.mcp_concurrency if payload and payload.mcp_concurrency else None) or cached_params.get("mcp_concurrency") or sess.get("mcp_concurrency", 2)
            temperature = (payload.temperature if payload is not None else None) if (payload and payload.temperature != 0.0) else cached_params.get("temperature", 0.0)
            max_tokens = (payload.max_tokens if payload and payload.max_tokens else None) or cached_params.get("max_tokens") or sess.get("max_tokens", 4096)
            sdet_phil = (payload.sdet_philosophy if payload and payload.sdet_philosophy else None) or cached_params.get("sdet_philosophy") or sess.get("sdet_philosophy", "Behavior-Driven Development (BDD)")
            cov_mode = (payload.coverage_mode if payload and payload.coverage_mode else None) or cached_params.get("coverage_mode") or sess.get("coverage_mode", "targeted")
            syn_engine = (payload.synthesis_engine if payload and payload.synthesis_engine else None) or cached_params.get("synthesis_engine") or sess.get("synthesis_engine", "Native Direct MCP")
            matrix_depth = (payload.matrix_depth if payload and payload.matrix_depth else None) or cached_params.get("matrix_depth") or sess.get("matrix_depth", "Standard / Sanity (5-8 tests)")
            multi_res = (payload.multi_resolution if payload is not None else None) if (payload and payload.multi_resolution) else cached_params.get("multi_resolution", False)
            parallel = (payload.parallel if payload is not None else None) if (payload and payload.parallel) else cached_params.get("parallel", True)
            vectors = (payload.vectors if payload and payload.vectors else None) or cached_params.get("vectors") or sess.get("vectors", ["Web UI Automation", "Master BDD Orchestration"])
            custom_prompts = (payload.custom_prompts if payload and payload.custom_prompts else None) or cached_params.get("custom_prompts") or sess.get("custom_prompts")
            selected_urls = (payload.selected_urls if payload and payload.selected_urls else None) or cached_params.get("selected_urls") or sess.get("selected_urls")
            custom_test_cnt = (payload.custom_test_count if payload and payload.custom_test_count else None) or cached_params.get("custom_test_count") or sess.get("custom_test_count")
            override_tokens = payload.override_token_check if payload else False

            if override_tokens:
                filtered_doms = dom_pages
            else:
                filtered_doms = [d for d in dom_pages if any(u in d for u in selected_urls)] if selected_urls else dom_pages
            if not filtered_doms: filtered_doms = dom_pages
            
            max_dom_chars = int(ctx_size * 2.2)
            combined_dom = "\n\n".join(filtered_doms) if cov_mode == "exhaustive" else "\n\n".join(filtered_doms)[:max_dom_chars]
            
            engine.emit_trace("DAEMON_STATUS", f"▶️ Resuming pipeline with {len(filtered_doms)} page scopes. Model: {model_name}, Workers: {concurrency}")
            
            contextual_analysis = engine.run_contextual_analysis(
                sess.get("url"), sess.get("detected_stack"), combined_dom, sess.get("apis", []),
                model_name, ctx_size, compute_strategy,
                temperature, max_tokens, steps,
                sdet_philosophy=sdet_phil,
                coverage_mode=cov_mode
            )

            final_res = engine.run_synthesis_and_assembly(
                sess.get("url"), sess.get("detected_stack"), sess.get("is_auth"), combined_dom,
                sess.get("apis", []), vectors, model_name, parallel,
                ctx_size, compute_strategy, concurrency,
                temperature, max_tokens, steps, custom_prompts,
                page_manifest=sess.get("page_manifest", []), username=sess.get("user", ""), password=sess.get("password", ""),
                sdet_philosophy=sdet_phil, llm_contextual_analysis=contextual_analysis,
                coverage_mode=cov_mode, multi_resolution=multi_res,
                matrix_depth=matrix_depth, synthesis_engine=syn_engine,
                custom_test_count=custom_test_cnt,
                selected_language=sess.get("selected_language", "Python"),
                selected_framework=sess.get("selected_framework", "Robot Framework + Pytest")
            )
            
            # Completed successfully - execute post-run cleanup while retaining tokens
            try:
                execute_post_run_cleanup(preserve_tokens=True, run_status="completed")
            except Exception:
                pass

        except Exception as e:
            trace = traceback.format_exc()
            with open("artifacts/logs/system_crash.log", "w", encoding="utf-8") as f: f.write(trace)
            with open("artifacts/logs/task_status.json", "w", encoding="utf-8") as f: json.dump({"status": "error", "error": str(e), "traceback": trace}, f)
            try:
                execute_post_run_cleanup(preserve_tokens=True, run_status="error")
            except Exception:
                pass

    in_process_pool.submit(resume_task_worker)
    return {"status": "resumed", "can_continue": False}

