@app.post("/api/chat/ask")
async def chat_ask(req: ChatRequest):
    def generate_chat():
        try:
            context_files = [
                "README.md",
                "artifacts/reports/Master_Requirements_Document.md",
                "artifacts/reports/master_requirements_document.md",
                "artifacts/reports/test_scenarios.md",
                "artifacts/reports/discovered_apis.json",
                "artifacts/reports/page_manifest.json"
            ]
            if os.path.exists("artifacts/scripts"):
                for root, _, files in os.walk("artifacts/scripts"):
                    for file in sorted(files):
                        if file.endswith((".py", ".js", ".robot", ".ts", ".java", ".md")):
                            context_files.append(os.path.join(root, file))
            
            system_prompt = "You are a Principal QA Automation Architect Assistant. Use the following project context to answer the user's questions or write new tests matching the established architecture. Only return code if explicitly asked. Keep answers concise.\n"
            system_prompt += "When you need to create or update a file based on the user's request, format your response exactly as follows:\n# FILE: <relative-path>\n```<lang>\n<content>\n```\nFor example: `# FILE: artifacts/scripts/my_test.py` followed by the markdown code block.\n\n"
            
            total_chars = 0
            MAX_CHARS = 12000
            for path in context_files:
                if os.path.exists(path) and os.path.getsize(path) < 150000:
                    try:
                        with open(path, "r", encoding="utf-8") as f:
                            content = f.read()
                            if total_chars + len(content) > MAX_CHARS:
                                break
                            system_prompt += f"=== {path} ===\n{content}\n\n"
                            total_chars += len(content)
                    except: pass
            
            messages = [{"role": "system", "content": system_prompt}]
            if req.history: messages.extend(req.history)
            messages.append({"role": "user", "content": req.message})
            
            ollama_url = os.environ.get("OLLAMA_ENDPOINT", "http://ollama_engine:11434/api/chat")
            if "/api/generate" in ollama_url: ollama_url = ollama_url.replace("/api/generate", "/api/chat")
            
            active_cfg = get_active_llm_config()
            vram_chat = probe_and_scale_vram_resources(req.model)
            
            # Use calibrated settings if set, else probe defaults
            scaled_ctx = (active_cfg.get("num_ctx") if active_cfg else None) or vram_chat.get("scaled_ctx", 8192)
            num_batch = (active_cfg.get("num_batch") if active_cfg else None) or vram_chat.get("num_batch", 1024)
            keep_alive_val = (active_cfg.get("keep_alive") if active_cfg else None) or "60m"
            num_threads = (active_cfg.get("threads") if active_cfg else None) or vram_chat.get("num_thread", 4)
            
            chat_options = {
                "num_ctx": scaled_ctx,
                "num_batch": num_batch,
                "num_thread": num_threads,
                "temperature": 0.2,
                "top_k": 20,
                "top_p": 0.5,
                "num_gpu": -1,
                "use_mmap": True,
                "f16_kv": True,
                "repeat_penalty": 1.0
            }
            response = requests.post(
                ollama_url,
                json={
                    "model": req.model, 
                    "messages": messages, 
                    "stream": True, 
                    "keep_alive": keep_alive_val,
                    "options": chat_options
                },
                stream=True,
                timeout=300
            )
            if response.status_code != 200:
                yield json.dumps({"error": f"Ollama API Error {response.status_code}"}) + "\n"
                return
            for line in response.iter_lines():
                if line: yield line.decode('utf-8') + "\n"
        except Exception as e:
            yield json.dumps({"error": str(e)}) + "\n"
    from fastapi.responses import StreamingResponse
    return StreamingResponse(generate_chat(), media_type="application/x-ndjson")

@app.get("/api/system/export")
def export_project():
    try:
        import zipfile, io
        from fastapi.responses import StreamingResponse
        zip_buffer = io.BytesIO()

        EXCLUDED_DIR_NAMES = {
            "ollama", "db", "storage", "tmp", "allure-2.24.1", "__pycache__", 
            ".pytest_cache", ".git", ".venv", "node_modules", "history", 
            "allure-report", "pabot_results", "generations", "screencast"
        }
        EXCLUDED_EXTENSIONS = {
            ".pyc", ".pyo", ".pyd", ".sock", ".lock", ".bin", ".tar", ".iso", ".img", ".tmp"
        }
        MAX_SINGLE_FILE_BYTES = 20 * 1024 * 1024

        with zipfile.ZipFile(zip_buffer, "w", zipfile.ZIP_DEFLATED, compresslevel=1) as zf:
            # 1. Scripts (all generated test suites)
            scripts_dir = "artifacts/scripts"
            if os.path.exists(scripts_dir):
                for root, dirs, files in os.walk(scripts_dir):
                    dirs[:] = [d for d in dirs if d.lower() not in EXCLUDED_DIR_NAMES and not d.startswith("chrome_")]
                    for file in files:
                        ext = os.path.splitext(file)[1].lower()
                        if ext in EXCLUDED_EXTENSIONS:
                            continue
                        file_path = os.path.join(root, file)
                        try:
                            if os.path.getsize(file_path) <= MAX_SINGLE_FILE_BYTES:
                                zf.write(file_path, os.path.relpath(file_path, "."))
                        except Exception:
                            continue

            # 2. Reports (all markdown requirements, specs, RTM, HTML summaries)
            reports_dir = "artifacts/reports"
            if os.path.exists(reports_dir):
                for item in os.listdir(reports_dir):
                    item_path = os.path.join(reports_dir, item)
                    if os.path.isfile(item_path):
                        ext = os.path.splitext(item)[1].lower()
                        if ext not in EXCLUDED_EXTENSIONS:
                            try:
                                if os.path.getsize(item_path) <= MAX_SINGLE_FILE_BYTES:
                                    zf.write(item_path, os.path.relpath(item_path, "."))
                            except Exception:
                                continue

            # 3. Config, libraries, tests harness
            for harness_dir in ["config", "libraries", "tests"]:
                if os.path.exists(harness_dir):
                    for root, dirs, files in os.walk(harness_dir):
                        dirs[:] = [d for d in dirs if d.lower() not in EXCLUDED_DIR_NAMES]
                        for file in files:
                            ext = os.path.splitext(file)[1].lower()
                            if ext not in EXCLUDED_EXTENSIONS:
                                file_path = os.path.join(root, file)
                                try:
                                    if os.path.getsize(file_path) <= MAX_SINGLE_FILE_BYTES:
                                        zf.write(file_path, os.path.relpath(file_path, "."))
                                except Exception:
                                    continue

            # 4. Root build & configuration manifests
            for root_file in [
                "pyproject.toml",
                "pytest.ini",
                "README.md",
                "artifacts/logs/task_status.json",
                "artifacts/logs/cached_user_params.json",
                "artifacts/logs/orchestrator.log"
            ]:
                if os.path.exists(root_file) and os.path.isfile(root_file):
                    try:
                        if os.path.getsize(root_file) <= MAX_SINGLE_FILE_BYTES:
                            zf.write(root_file, os.path.relpath(root_file, "."))
                    except Exception:
                        continue

            # 5. Execution engine trace (instant tail seek without scanning entire file)
            engine_trace_path = "artifacts/logs/engine_trace.jsonl"
            if os.path.exists(engine_trace_path) and os.path.isfile(engine_trace_path):
                try:
                    et_size = os.path.getsize(engine_trace_path)
                    with open(engine_trace_path, "rb") as et_f:
                        if et_size > 100_000:
                            et_f.seek(et_size - 100_000)
                        tail_bytes = et_f.read()
                    zf.writestr(engine_trace_path, tail_bytes)
                except Exception:
                    pass

        zip_buffer.seek(0)
        from fastapi.responses import Response
        return Response(
            content=zip_buffer.getvalue(),
            media_type="application/zip",
            headers={"Content-Disposition": "attachment; filename=qa_project_export.zip"}
        )
    except Exception as e:
        return {"status": "error", "message": str(e)}

def _project_import_status(status: str, message: str, **details):
    os.makedirs("artifacts/logs", exist_ok=True)
    payload = {"status": status, "message": message, "updated_at": datetime.now().strftime("%Y-%m-%d %H:%M:%S"), **details}
    with open("artifacts/logs/project_import_status.json", "w", encoding="utf-8") as status_file:
        json.dump(payload, status_file, indent=2)
    return payload

def _stop_active_work_for_import():
    global active_harness
    _project_import_status("stopping", "Stopping active project execution before import.")
    if active_harness:
        try: active_harness.stop()
        except Exception: pass
    try: execute_post_run_cleanup(preserve_tokens=True, run_status="stopped_for_import")
    except Exception: pass

def _restore_project_archive(archive_path: str, source_name: str):
    import tempfile
    with zipfile.ZipFile(archive_path, "r") as zip_ref:
        members = [member for member in zip_ref.infolist() if not member.is_dir()]
        if not members: raise ValueError("Project archive contains no files.")
        base_dir = os.path.abspath(".")
        allowed_members = []
        for member in members:
            destination = os.path.abspath(os.path.join(base_dir, member.filename))
            parts = os.path.normpath(member.filename).lower().split(os.sep)
            if os.path.commonpath([base_dir, destination]) != base_dir:
                raise ValueError("Project archive contains an unsafe path.")
            if any(part in parts for part in ["ollama", "db", "storage", "allure-2.24.1", ".git", "__pycache__"]): continue
            allowed_members.append(member)
        if not allowed_members: raise ValueError("Project archive contains no importable project files.")
        with tempfile.TemporaryDirectory(prefix="atp_project_import_") as staging_dir:
            for member in allowed_members: zip_ref.extract(member, staging_dir)
            _stop_active_work_for_import()
            for directory in ["artifacts/scripts", "artifacts/reports"]:
                if os.path.exists(directory): shutil.rmtree(directory, ignore_errors=True)
                os.makedirs(directory, exist_ok=True)
            for member in allowed_members:
                staged_path = os.path.join(staging_dir, member.filename)
                destination = os.path.join(base_dir, member.filename)
                if os.path.exists(staged_path):
                    os.makedirs(os.path.dirname(destination), exist_ok=True)
                    shutil.copy2(staged_path, destination)
    cache_dir = os.path.join("artifacts", "import_cache")
    os.makedirs(cache_dir, exist_ok=True)
    cached_archive = os.path.join(cache_dir, "last_project_import.zip")
    shutil.copy2(archive_path, cached_archive)
    return _project_import_status("completed", f"Project restored from {source_name}.", restored_count=len(allowed_members), cached_archive=cached_archive, reimport_ready=True)

@app.post("/api/system/import")
async def import_system_project(file: UploadFile = File(...)):
    temp_zip = os.path.join("artifacts", "import_cache", "incoming_project.zip")
    try:
        if not project_import_lock.acquire(blocking=False):
            return JSONResponse(status_code=409, content={"status": "busy", "message": "Another project import is already in progress."})
        os.makedirs(os.path.dirname(temp_zip), exist_ok=True)
        with open(temp_zip, "wb") as f: f.write(await file.read())
        result = await asyncio.to_thread(_restore_project_archive, temp_zip, file.filename or "uploaded archive")
        try: broadcast_ws({"type": "PROJECT_RELOADED", "message": result["message"], "restored_count": result["restored_count"]})
        except Exception: pass
        return {"status": "success", **result}
    except Exception as e:
        _project_import_status("error", f"Project import failed: {e}")
        return {"status": "error", "message": str(e)}
    finally:
        if os.path.exists(temp_zip):
            try: os.remove(temp_zip)
            except Exception: pass
        if project_import_lock.locked(): project_import_lock.release()

@app.post("/api/system/import/retry")
async def retry_system_project_import():
    cached_archive = os.path.join("artifacts", "import_cache", "last_project_import.zip")
    if not os.path.exists(cached_archive):
        return JSONResponse(status_code=404, content={"status": "error", "message": "No validated project import is available to re-run."})
    if not project_import_lock.acquire(blocking=False):
        return JSONResponse(status_code=409, content={"status": "busy", "message": "Another project import is already in progress."})
    try:
        result = await asyncio.to_thread(_restore_project_archive, cached_archive, "cached project import")
        return {"status": "success", **result}
    except Exception as e:
        _project_import_status("error", f"Cached project import failed: {e}")
        return {"status": "error", "message": str(e)}
    finally:
        project_import_lock.release()

